(()=>{'use strict';
const $=(selector,root=document)=>root.querySelector(selector);const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const icons=window.RSV_ICONS||{};function renderIcon(target,name){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('aria-hidden','true');svg.classList.add('hgi');for(const [tag,attrs]of icons[name]||[]){const el=document.createElementNS(ns,tag);for(const [key,value]of Object.entries(attrs)){if(key!=='key')el.setAttribute(key.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()),value)}svg.append(el)}target.replaceChildren(svg)}$$('[data-icon]').forEach(el=>renderIcon(el,el.dataset.icon));
const motion=matchMedia('(prefers-reduced-motion: reduce)'),desktop=matchMedia('(min-width: 801px)');const header=$('.site-header'),hero=$('.hero'),film=$('.precision-film'),stage=$('.precision-stage'),image=$('.precision-image');
const chapterData=[{kicker:'ДИАГНОСТИКА',title:'Понять. До того,\nкак ремонтировать.',description:'Чек-ап RSV помогает увидеть состояние автомобиля в целом. Находим причины неисправностей и объясняем, что действительно требует внимания.',action:'Обсудить чек-ап',service:'Чек-ап RSV'},{kicker:'ПОНЯТНЫЙ ПЛАН',title:'Согласовать.\nКаждое решение.',description:'Обсуждаем приоритеты, запчасти, стоимость и сроки. Объединяем связанные работы, чтобы не возвращаться к одной задаче дважды.',action:'Обсудить задачу',service:'Нужна консультация'},{kicker:'ВНИМАНИЕ ДО РЕЗУЛЬТАТА',title:'Сделать точно.\nОбъяснить результат.',description:'Выполняем согласованные работы, рассказываем о результате и передаём документы. Помогаем понимать, какое обслуживание потребуется дальше.',action:'Доверить автомобиль',service:'Нужна консультация'}];
let chapter=0,manualChapter=false;const chapterButtons=$$('[data-chapter]'),chapterBlock=$('.chapter-copy');function setChapter(index,animate=true){if(index===chapter)return;chapter=index;const data=chapterData[index];$('#chapter-number').textContent=String(index+1).padStart(2,'0');$('#chapter-kicker').textContent=data.kicker;const title=$('#chapter-title');title.replaceChildren();data.title.split('\n').forEach((line,i)=>{if(i)title.append(document.createElement('br'));title.append(document.createTextNode(line))});$('#chapter-description').textContent=data.description;const action=$('#chapter-action');action.dataset.book=data.service;action.replaceChildren(document.createTextNode(data.action+' '));const icon=document.createElement('span');renderIcon(icon,'ArrowUpRight01Icon');action.append(icon);chapterButtons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));if(animate&&!motion.matches)chapterBlock.animate([{opacity:.25,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.16,1,.3,1)'})}
chapterButtons.forEach(button=>button.addEventListener('click',()=>{manualChapter=true;setChapter(Number(button.dataset.chapter))}));
let queued=false;function syncScroll(){header.classList.toggle('scrolled',scrollY>35);if(!motion.matches){const rect=hero.getBoundingClientRect(),p=Math.min(1,Math.max(0,-rect.top/rect.height));hero.style.setProperty('--hero-shift',`${p*50}px`);hero.style.setProperty('--hero-opacity',String(1-p*.65));if(desktop.matches){const filmRect=film.getBoundingClientRect(),range=Math.max(1,film.offsetHeight-stage.offsetHeight),progress=Math.min(1,Math.max(0,-filmRect.top/range));image.style.setProperty('--detail-scale',String(1+progress*.09));image.style.setProperty('--detail-x',`${-2+progress*3}%`);if(filmRect.top<0&&filmRect.bottom>stage.offsetHeight&&!manualChapter)setChapter(Math.min(2,Math.floor(progress*3)));}}queued=false}
addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(syncScroll)}},{passive:true});addEventListener('resize',syncScroll);motion.addEventListener('change',()=>{hero.style.removeProperty('--hero-shift');hero.style.removeProperty('--hero-opacity');syncScroll()});syncScroll();
if('IntersectionObserver'in window&&!motion.matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('will-reveal');observer.observe(el)}});motion.addEventListener('change',e=>{if(e.matches){$$('.will-reveal').forEach(el=>el.classList.add('is-visible'));observer.disconnect()}})}
const nav=$('#main-navigation'),menu=$('.menu-toggle');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Открыть меню');renderIcon($('[data-icon]',menu),'Menu01Icon')}menu.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');renderIcon($('[data-icon]',menu),open?'Cancel01Icon':'Menu01Icon')});$$('a',nav).forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
const dialog=$('#booking'),select=$('#service-select');let trigger=null;document.addEventListener('click',e=>{const button=e.target.closest('[data-book]');if(!button)return;trigger=button;const requested=button.dataset.book||'Нужна консультация';select.value=[...select.options].some(option=>option.value===requested)?requested:'Нужна консультация';$('#form-result').replaceChildren();closeMenu();dialog.showModal();document.body.classList.add('modal-open')});$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(trigger?.isConnected)trigger.focus({preventScroll:true})});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
$('#booking-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const body=`Здравствуйте! Хочу записаться в RSV Service.\n\nИмя: ${data.get('name')}\nТелефон: ${data.get('phone')}\nАвтомобиль: ${data.get('car')}\nЗадача: ${data.get('service')}\nКомментарий: ${data.get('note')}\n\nПрошу уточнить время и адрес визита.`;const url=`mailto:rsvservice@yandex.ru?subject=${encodeURIComponent('Запись в RSV Service: '+data.get('service'))}&body=${encodeURIComponent(body)}`;const result=$('#form-result');result.replaceChildren();result.append('Письмо подготовлено. Отправьте его в почтовой программе. Если она не открылась, ');const link=document.createElement('a');link.href=url;link.textContent='откройте письмо повторно';result.append(link,'. Или позвоните: +7 (960) 350-46-93.');window.location.href=url});
})();
